using System.Buffers.Binary;
using System.Text.Json;
using System.Text.Json.Nodes;
using Stardust.Core.Protocol;
namespace Stardust.Core.SmokeTests;
public static class CreatureView4Scenarios
{
    private static object Text(ReplicationByteString t)=>new{Hex=Convert.ToHexString(t.CopyBytes()),Extended=t.UsesExtendedLength};
    private static object Model(CreatureView4Baseline m)=>new{m.ObjectId,m.DeclaredCount,FloatBits=m.FloatBits.ToArray(),m.ListenTo,Encumbrances=new{m.Encumbrances.Counter,Values=m.Encumbrances.Values.ToArray()},SkillMods=new{m.SkillMods.Counter,Values=m.SkillMods.Values.Select(v=>new{v.RawCommand,Name=Text(v.Name),v.BaseValue,v.Bonus}).ToArray()},SpaceMissionObjects=new{m.SpaceMissionObjects.Counter,Values=m.SpaceMissionObjects.Values.ToArray()}};
    private static object Row(CreatureView4State s)=>new{Model=Model(s.Model),s.Revision,s.DecodedBytes};
    private static object Plan(CreatureView4Delta p)=>new{p.ObjectId,p.DeclaredCount,Updates=p.Updates.Select(v=>new{v.Index,v.Bits}).ToArray()};
    public static void Run(string input,string output)
    {
        if(new FileInfo(input).Length>33554432)throw new InvalidDataException("Bounded synthetic CREO4 fixture");using var doc=JsonDocument.Parse(File.ReadAllBytes(input));var records=new List<object>();int negatives=0,budgets=0,ownership=0;var limits=new CreatureView4Limits();
        void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        void Equal(object value,JsonElement expected,string why)=>Check(JsonNode.DeepEquals(JsonSerializer.SerializeToNode(value),JsonNode.Parse(expected.GetRawText())),why);
        void Reject(Action a){negatives++;try{a();}catch(InvalidDataException){return;}catch(ArgumentException){return;}catch(OverflowException){return;}throw new Exception("CREO4 negative accepted");}
        CreatureView4Limits Cost(JsonElement c)=>new(c.GetProperty("Payload").GetInt32(),c.GetProperty("Fields").GetInt32(),c.GetProperty("Elements").GetInt32(),c.GetProperty("TotalElements").GetInt32(),c.GetProperty("MaxString").GetInt32(),c.GetProperty("Strings").GetInt32(),c.GetProperty("Decoded").GetInt64(),c.GetProperty("Work").GetInt64());
        List<CreatureView4Limits> Less(CreatureView4Limits l)
        {
            var result=new List<CreatureView4Limits>{l with{MaximumPayloadBytes=l.MaximumPayloadBytes-1},l with{MaximumFields=l.MaximumFields-1},l with{MaximumDecodedBytes=l.MaximumDecodedBytes-1},l with{MaximumWork=l.MaximumWork-1}};
            if(l.MaximumElements>0)result.Add(l with{MaximumElements=l.MaximumElements-1});if(l.MaximumTotalElements>0)result.Add(l with{MaximumTotalElements=l.MaximumTotalElements-1});if(l.MaximumStringBytes>0)result.Add(l with{MaximumStringBytes=l.MaximumStringBytes-1});if(l.MaximumTotalStringBytes>0)result.Add(l with{MaximumTotalStringBytes=l.MaximumTotalStringBytes-1});return result;
        }
        foreach(var c in doc.RootElement.GetProperty("Cases").EnumerateArray())
        {
            var bw=Convert.FromHexString(c.GetProperty("Baseline").GetString()!);var wire=Convert.FromHexString(c.GetProperty("Hex").GetString()!);var baseline=CreatureView4Codec.DecodeBaseline(bw,limits);var p=CreatureView4Codec.DecodeDelta(wire,limits);
            Check(CreatureView4Codec.EncodeBaseline(baseline,limits).SequenceEqual(bw),"Exact raw baseline bytes");Check(CreatureView4Codec.EncodeDelta(p,limits).SequenceEqual(wire),"Exact scalar bytes");Equal(Plan(p),c.GetProperty("Plan"),"Independent scalar plan");
            Equal(Model(CreatureView4Codec.DecodeBaseline(ReplicationEnvelopeCodec.DecodeBaseline(bw,limits.MaximumPayloadBytes),limits)),c.GetProperty("Initial").GetProperty("Model"),"Public baseline envelope overload");Equal(Plan(CreatureView4Codec.DecodeDelta(ReplicationEnvelopeCodec.DecodeDelta(wire,limits.MaximumPayloadBytes),limits)),c.GetProperty("Plan"),"Public delta envelope overload");
            Check(ReplicationEnvelopeCodec.EncodeBaseline(CreatureView4Codec.EncodeBaselineEnvelope(baseline,limits),limits.MaximumPayloadBytes).SequenceEqual(bw),"Baseline envelope encode");Check(ReplicationEnvelopeCodec.EncodeDelta(CreatureView4Codec.EncodeDeltaEnvelope(p,limits),limits.MaximumPayloadBytes).SequenceEqual(wire),"Delta envelope encode");
            var state=CreatureView4State.FromBaseline(baseline,new(MaximumWork:16777216));Equal(Row(state),c.GetProperty("Initial"),"Independent complete seed");string old=JsonSerializer.Serialize(Row(state));var change=state.Apply(p);Equal(Row(change.Current),c.GetProperty("Expected"),"Independent full scalar model");Equal(change.Events,c.GetProperty("Events"),"Independent ordered assignment descriptions");Check(change.WorkUsed==c.GetProperty("Work").GetInt64(),"Exact state logical work");Check(change.Current.Revision==2&&change.DeclaredCount==65535&&change.DecodedOutputBytes==change.Current.DecodedBytes+24L*change.Events.Count,"Revision/raw metadata/24-byte receipt");Check(JsonSerializer.Serialize(Row(state))==old,"Immutable previous state");ownership++;
            var alias=(byte[])bw.Clone();var owned=CreatureView4Codec.DecodeBaseline(alias,limits);Array.Clear(alias);Check(CreatureView4Codec.EncodeBaseline(owned,limits).SequenceEqual(bw),"Owned baseline wire");ownership++;
            alias=(byte[])wire.Clone();var ownedDelta=CreatureView4Codec.DecodeDelta(alias,limits);Array.Clear(alias);Check(CreatureView4Codec.EncodeDelta(ownedDelta,limits).SequenceEqual(wire),"Owned scalar wire");ownership++;
            var floats=baseline.FloatBits.ToArray();var enc=baseline.Encumbrances.Values.ToArray();var missions=baseline.SpaceMissionObjects.Values.ToArray();var keys=new List<byte[]>();var skills=baseline.SkillMods.Values.Select(v=>{var raw=v.Name.CopyBytes();keys.Add(raw);return new CreatureView4SkillMod(v.RawCommand,ReplicationByteString.Create(raw,v.Name.UsesExtendedLength),v.BaseValue,v.Bonus);}).ToArray();
            var frozen=new CreatureView4Baseline(baseline.ObjectId,baseline.DeclaredCount,floats,baseline.ListenTo,new(baseline.Encumbrances.Counter,enc),new(baseline.SkillMods.Counter,skills),new(baseline.SpaceMissionObjects.Counter,missions));Array.Clear(floats);Array.Clear(enc);Array.Clear(skills);Array.Clear(missions);foreach(var key in keys)Array.Clear(key);Check(CreatureView4Codec.EncodeBaseline(frozen,limits).SequenceEqual(bw),"Nested baseline/entry/string ownership");ownership+=4+keys.Count;
            var updates=p.Updates.ToArray();var frozenPlan=new CreatureView4Delta(p.ObjectId,p.DeclaredCount,updates);Array.Clear(updates);Check(CreatureView4Codec.EncodeDelta(frozenPlan,limits).SequenceEqual(wire),"Ordered plan ownership");ownership++;
            Equal(Row(Task.Run(()=>state.Apply(p)).GetAwaiter().GetResult().Current),c.GetProperty("Expected"),"Concurrent immutable branch");ownership++;
            var bc=Cost(c.GetProperty("BaselineCost"));var dc=Cost(c.GetProperty("CodecCost"));_=CreatureView4Codec.DecodeBaseline(bw,bc);Check(CreatureView4Codec.EncodeBaseline(baseline,bc).SequenceEqual(bw),"Exact baseline caps");_=CreatureView4Codec.DecodeDelta(wire,dc);Check(CreatureView4Codec.EncodeDelta(p,dc).SequenceEqual(wire),"Exact delta caps");budgets+=4;
            foreach(var l in Less(bc)){Reject(()=>CreatureView4Codec.DecodeBaseline(bw,l));Reject(()=>CreatureView4Codec.EncodeBaseline(baseline,l));budgets+=2;}foreach(var l in Less(dc)){Reject(()=>CreatureView4Codec.DecodeDelta(wire,l));Reject(()=>CreatureView4Codec.EncodeDelta(p,l));budgets+=2;}
            var sc=c.GetProperty("StateCost");int N(string k)=>sc.GetProperty(k).GetInt32();long L(string k)=>sc.GetProperty(k).GetInt64();var sl=new CreatureView4StateLimits(N("Updates"),N("Elements"),N("TotalElements"),N("MaxString"),N("Strings"),L("StateBytes"),N("Events"),L("OutputBytes"),L("Work"));var exact=state.Apply(p,sl);Equal(Row(exact.Current),c.GetProperty("Expected"),"Exact complete state caps");budgets++;
            var less=new List<CreatureView4StateLimits>{sl with{MaximumUpdates=sl.MaximumUpdates-1},sl with{MaximumStateBytes=sl.MaximumStateBytes-1},sl with{MaximumEvents=sl.MaximumEvents-1},sl with{MaximumOutputBytes=sl.MaximumOutputBytes-1},sl with{MaximumWork=sl.MaximumWork-1}};if(sl.MaximumElements>0)less.Add(sl with{MaximumElements=sl.MaximumElements-1});if(sl.MaximumTotalElements>0)less.Add(sl with{MaximumTotalElements=sl.MaximumTotalElements-1});if(sl.MaximumStringBytes>0)less.Add(sl with{MaximumStringBytes=sl.MaximumStringBytes-1});if(sl.MaximumTotalStringBytes>0)less.Add(sl with{MaximumTotalStringBytes=sl.MaximumTotalStringBytes-1});foreach(var l in less){Reject(()=>state.Apply(p,l));Check(JsonSerializer.Serialize(Row(state))==old,"Failed plan preserves complete state");budgets++;}
            var seedExact=sl with{MaximumWork=L("SeedWork"),MaximumOutputBytes=L("StateBytes")};_=CreatureView4State.FromBaseline(baseline,seedExact);Reject(()=>CreatureView4State.FromBaseline(baseline,seedExact with{MaximumWork=seedExact.MaximumWork-1}));Reject(()=>CreatureView4State.FromBaseline(baseline,seedExact with{MaximumOutputBytes=seedExact.MaximumOutputBytes-1}));budgets+=3;
            var reseed=change.Current.Reseed(baseline);Equal(Row(reseed),c.GetProperty("Reseed"),"Reseed raw full model");Reject(()=>state.Apply(new(p.ObjectId+1,p.DeclaredCount,p.Updates)));var wrong=new CreatureView4Baseline(baseline.ObjectId+1,baseline.DeclaredCount,baseline.FloatBits,baseline.ListenTo,baseline.Encumbrances,baseline.SkillMods,baseline.SpaceMissionObjects);Reject(()=>state.Reseed(wrong));Reject(()=>CreatureView4State.FromBaseline(baseline,null,ulong.MaxValue));var end=CreatureView4State.FromBaseline(baseline,null,ulong.MaxValue-1);Reject(()=>end.Apply(p));Reject(()=>end.Reseed(baseline));
            for(int n=0;n<bw.Length;n++){var partial=bw[..n];Reject(()=>CreatureView4Codec.DecodeBaseline(partial,limits));if(n>=25){BinaryPrimitives.WriteUInt32LittleEndian(partial.AsSpan(19),(uint)(n-23));Reject(()=>CreatureView4Codec.DecodeBaseline(partial,limits));}}
            var valid=c.GetProperty("ValidPrefixes").EnumerateArray().Select(v=>v.GetInt32()).ToHashSet();for(int n=0;n<wire.Length;n++){var partial=wire[..n];Reject(()=>CreatureView4Codec.DecodeDelta(partial,limits));if(n>=25){BinaryPrimitives.WriteUInt32LittleEndian(partial.AsSpan(19),(uint)(n-23));try{var prefix=CreatureView4Codec.DecodeDelta(partial,limits);Check(valid.Contains(n),"Independent legal scalar prefix");Check(CreatureView4Codec.EncodeDelta(prefix,limits).SequenceEqual(partial),"Exact legal adjusted prefix");}catch(InvalidDataException){Check(!valid.Contains(n),"Independent illegal scalar prefix");negatives++;}}}
            string retained=JsonSerializer.Serialize(Row(change.Current));Reject(()=>change.Current.Apply(p,sl with{MaximumWork=0}));Check(JsonSerializer.Serialize(Row(change.Current))==retained,"Earlier publication survives later failure");ownership++;
            records.Add(new{Name=c.GetProperty("Name").GetString(),Plan=Plan(p),Initial=Row(state),Expected=Row(change.Current),Events=change.Events,Work=change.WorkUsed,Reseed=Row(reseed)});
        }
        foreach(var m in doc.RootElement.GetProperty("Malformed").EnumerateArray()){var raw=Convert.FromHexString(m.GetProperty("Hex").GetString()!);if(m.GetProperty("Kind").GetString()=="Baseline")Reject(()=>CreatureView4Codec.DecodeBaseline(raw,limits));else Reject(()=>CreatureView4Codec.DecodeDelta(raw,limits));}
        foreach(ushort field in new ushort[]{2,3,13,14,65535})Reject(()=>new CreatureView4Update(field,0));Reject(()=>new CreatureView4Update(0,1UL<<32));Reject(()=>CreatureView4Codec.EncodeDelta(new(1,0,[]),limits));Reject(()=>new CreatureView4Delta(1,0,[null!]));Reject(()=>new CreatureView4Collection<CreatureView4SkillMod>(0,[null!]));Reject(()=>new CreatureView4SkillMod(0,null!,0,0));Reject(()=>CreatureView4Codec.DecodeDelta([],limits with{MaximumPayloadBytes=8388609}));Reject(()=>CreatureView4Codec.DecodeBaseline([],limits with{MaximumPayloadBytes=8388609}));
        File.WriteAllText(output,JsonSerializer.Serialize(new{Records=records,Negatives=negatives,Budgets=budgets,Ownership=ownership},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"PASS CREO4 {records.Count} exact cases, {negatives} negatives, {budgets} budgets, {ownership} ownership checks");
    }
}
